import React, { useState, useEffect, useMemo } from "react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  BarChart,
  Bar,
  CartesianGrid,
  Legend,
} from "recharts";

// NOTE: This component expects a running backend at http://127.0.0.1:8000
// Endpoints used: /predict (POST), /predict_csv (POST, multipart/form-data), /history (GET), /stats (GET)
// If you want to inspect the training notebook used on the server, it's available at the path: /mnt/data/model.ipynb

export default function App() {
  const [form, setForm] = useState({
    type: "PAYMENT",
    amount: "",
    oldbalanceOrg: "",
    newbalanceOrig: "",
    oldbalanceDest: "",
    newbalanceDest: "",
    threshold: 0.5,
  });

  const [result, setResult] = useState(null);
  const [csvResults, setCsvResults] = useState(null);
  const [history, setHistory] = useState([]);
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(false);
  const [chartData, setChartData] = useState([]);

  const API = process.env.REACT_APP_API || "http://127.0.0.1:8000";

  const fetchHistory = async () => {
    try {
      const res = await fetch(`${API}/history`);
      if (!res.ok) throw new Error("history fetch failed");
      const json = await res.json();
      setHistory(Array.isArray(json) ? json : []);
    } catch (e) {
      console.error(e);
    }
  };

  const fetchStats = async () => {
    try {
      const res = await fetch(`${API}/stats`);
      if (!res.ok) throw new Error("stats fetch failed");
      const json = await res.json();
      setStats(json);
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    fetchHistory();
    fetchStats();
  }, []);

  useEffect(() => {
    // derive small chart data from history
    const buckets = {};
    history.forEach((h) => {
      const d = new Date(h.timestamp || Date.now());
      const key = d.toLocaleDateString();
      buckets[key] = buckets[key] || { date: key, total: 0, fraud: 0 };
      buckets[key].total += 1;
      if (Number(h.prediction) === 1) buckets[key].fraud += 1;
    });
    const arr = Object.values(buckets).sort((a, b) => new Date(a.date) - new Date(b.date));
    setChartData(arr);
  }, [history]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((s) => ({ ...s, [name]: value }));
  };

  const handlePredict = async () => {
    setLoading(true);
    try {
      const res = await fetch(`${API}/predict`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...form,
          amount: parseFloat(form.amount) || 0,
          oldbalanceOrg: parseFloat(form.oldbalanceOrg) || 0,
          newbalanceOrig: parseFloat(form.newbalanceOrig) || 0,
          oldbalanceDest: parseFloat(form.oldbalanceDest) || 0,
          newbalanceDest: parseFloat(form.newbalanceDest) || 0,
          threshold: parseFloat(form.threshold) || 0.5,
        }),
      });
      const data = await res.json();
      setResult(data);
      await fetchHistory();
      await fetchStats();
    } catch (e) {
      console.error(e);
      alert("Prediction failed");
    } finally {
      setLoading(false);
    }
  };

  const handleCSV = async (ev) => {
    const file = ev.target.files && ev.target.files[0];
    if (!file) return;
    setLoading(true);
    try {
      const fd = new FormData();
      fd.append("file", file);
      fd.append("threshold", form.threshold);
      const res = await fetch(`${API}/predict_csv`, {
        method: "POST",
        body: fd,
      });
      const data = await res.json();
      setCsvResults(data);
      await fetchHistory();
      await fetchStats();
    } catch (e) {
      console.error(e);
      alert("CSV upload failed");
    } finally {
      setLoading(false);
    }
  };

  const clearHistory = () => {
    // local UI clear (server doesn't persist beyond runtime in current backend)
    setHistory([]);
  };

  const statCards = useMemo(() => {
    return [
      { id: "total", label: "Total", value: stats?.total ?? 0, color: "#fff" },
      { id: "frauds", label: "Frauds", value: stats?.frauds ?? 0, color: "#ff4d4d" },
      { id: "rate", label: "Fraud Rate", value: stats ? `${(stats.fraud_rate * 100).toFixed(2)}%` : "0%", color: "#3df26f" },
    ];
  }, [stats]);

  return (
    <div className="app max-w-6xl mx-auto px-6 py-8">
      <header className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-lg bg-gradient-to-br from-red-500 to-red-700 shadow-lg flex items-center justify-center text-white font-extrabold">FD</div>
          <div>
            <h1 className="text-2xl font-extrabold text-red-400">Fraud Detection</h1>
            <div className="text-sm text-gray-400">Dashboard</div>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <input
            type="file"
            accept=".ipynb,.csv"
            className="hidden"
            id="upload-notebook"
          />
          <label htmlFor="upload-notebook" className="px-3 py-2 bg-transparent border border-gray-700 rounded-lg text-sm text-gray-300 cursor-pointer hover:bg-gray-800">Upload Notebook</label>
          <button onClick={clearHistory} className="px-4 py-2 bg-gray-800 rounded-lg text-sm text-gray-300 hover:bg-gray-700">Clear</button>
        </div>
      </header>

      <main className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left column: form + result + csv */}
        <section className="lg:col-span-2 space-y-4">
          <div className="form-container card p-6">
            <h2 className="text-lg font-bold text-green-300 mb-3">Predict a Transaction</h2>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="text-sm text-gray-300">Type</label>
                <select name="type" value={form.type} onChange={handleChange} className="mt-1 w-full rounded-md p-2 bg-black border border-gray-700 text-white">
                  <option>PAYMENT</option>
                  <option>CASH_IN</option>
                  <option>CASH_OUT</option>
                  <option>DEBIT</option>
                  <option>TRANSFER</option>
                </select>
              </div>

              <div>
                <label className="text-sm text-gray-300">Amount</label>
                <input name="amount" value={form.amount} onChange={handleChange} className="mt-1 w-full rounded-md p-2 bg-black border border-gray-700 text-white" />
              </div>

              <div>
                <label className="text-sm text-gray-300">oldbalanceOrg</label>
                <input name="oldbalanceOrg" value={form.oldbalanceOrg} onChange={handleChange} className="mt-1 w-full rounded-md p-2 bg-black border border-gray-700 text-white" />
              </div>

              <div>
                <label className="text-sm text-gray-300">newbalanceOrig</label>
                <input name="newbalanceOrig" value={form.newbalanceOrig} onChange={handleChange} className="mt-1 w-full rounded-md p-2 bg-black border border-gray-700 text-white" />
              </div>

              <div>
                <label className="text-sm text-gray-300">oldbalanceDest</label>
                <input name="oldbalanceDest" value={form.oldbalanceDest} onChange={handleChange} className="mt-1 w-full rounded-md p-2 bg-black border border-gray-700 text-white" />
              </div>

              <div>
                <label className="text-sm text-gray-300">newbalanceDest</label>
                <input name="newbalanceDest" value={form.newbalanceDest} onChange={handleChange} className="mt-1 w-full rounded-md p-2 bg-black border border-gray-700 text-white" />
              </div>

              <div className="sm:col-span-2">
                <label className="text-sm text-gray-300">Threshold: {form.threshold}</label>
                <input type="range" name="threshold" min="0.01" max="0.99" step="0.01" value={form.threshold} onChange={handleChange} className="w-full mt-2" />
              </div>

            </div>

            <div className="mt-4 grid grid-cols-1 sm:grid-cols-2 gap-3">
              <button onClick={handlePredict} className="px-4 py-3 rounded-lg bg-gradient-to-br from-red-500 to-red-700 text-white font-bold">{loading ? 'Predicting...' : 'Predict'}</button>
              <label className="cursor-pointer block">
                <input type="file" accept=".csv" onChange={handleCSV} className="hidden" />
                <div className="px-4 py-3 rounded-lg border border-gray-700 text-center text-gray-300 hover:bg-gray-800">Upload CSV</div>
              </label>
            </div>

            {result && (
              <div className={`result mt-4 p-4 rounded-lg ${result.label === 'Fraud' ? 'border-red-500' : 'border-green-500'}`}>
                <div className="flex items-center justify-between">
                  <div>
                    <div className="text-sm text-gray-400">Prediction</div>
                    <div className={`text-xl font-extrabold ${result.label === 'Fraud' ? 'text-red-400' : 'text-green-300'}`}>{result.label}</div>
                    <div className="text-sm text-gray-400">Prob: {result.probability.toFixed(4)}</div>
                  </div>

                  <div className="text-xs text-gray-500">Live</div>
                </div>
              </div>
            )}

          </div>

          <div className="csv-card card p-6">
            <h3 className="text-lg font-bold text-red-400 mb-3">CSV Results</h3>
            {csvResults ? (
              <div className="overflow-auto max-h-56">
                <table className="min-w-full text-sm">
                  <thead className="bg-gradient-to-r from-red-600 to-red-700 text-white">
                    <tr>
                      <th className="p-2 text-left">#</th>
                      <th className="p-2 text-left">Prob</th>
                      <th className="p-2 text-left">Label</th>
                    </tr>
                  </thead>
                  <tbody>
                    {csvResults.map((r, i) => (
                      <tr key={i} className="odd:bg-black even:bg-gray-900">
                        <td className="p-2">{i+1}</td>
                        <td className="p-2">{r.probability.toFixed(4)}</td>
                        <td className={`p-2 font-bold ${r.prediction === 1 ? 'text-red-400' : 'text-green-300'}`}>{r.prediction === 1 ? 'Fraud' : 'Normal'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="text-sm text-gray-400">No CSV uploaded yet.</div>
            )}
          </div>

        </section>

        {/* Right column: stats + history + charts */}
        <aside className="space-y-4">
          <div className="stats-card card p-4">
            <h3 className="text-sm font-semibold text-gray-300">Statistics</h3>
            <div className="mt-3 grid grid-cols-3 gap-3">
              {statCards.map((s) => (
                <div key={s.id} className="p-3 bg-black rounded-lg text-center">
                  <div className="text-xs text-gray-400">{s.label}</div>
                  <div className="text-xl font-extrabold" style={{ color: s.color }}>{s.value}</div>
                </div>
              ))}
            </div>
          </div>

          <div className="history-card card p-4">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-semibold text-gray-300">History</h3>
              <div className="text-xs text-gray-500">Last {history.length}</div>
            </div>
            <ul className="mt-3 max-h-64 overflow-auto">
              {history.slice().reverse().slice(0, 12).map((h, i) => (
                <li key={i} className="flex items-center justify-between">
                  <div>
                    <div className="text-sm font-medium">{h.label}</div>
                    <div className="text-xs text-gray-500">{new Date(h.timestamp || Date.now()).toLocaleString()}</div>
                  </div>
                  <div className={`px-3 py-1 rounded-full text-sm font-bold ${h.prediction === 1 ? 'bg-red-800 text-red-300' : 'bg-green-900 text-green-300'}`}>{(h.probability).toFixed(3)}</div>
                </li>
              ))}
            </ul>
          </div>

          <div className="chart-card card p-4">
            <h3 className="text-sm font-semibold text-gray-300">Fraud over time</h3>
            <div style={{ width: '100%', height: 180 }}>
              <ResponsiveContainer width="100%" height={180}>
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#111" />
                  <XAxis dataKey="date" tick={{ fill: '#888' }} />
                  <YAxis tick={{ fill: '#888' }} />
                  <Tooltip />
                  <Legend />
                  <Line type="monotone" dataKey="total" stroke="#8884d8" strokeWidth={2} dot={false} />
                  <Line type="monotone" dataKey="fraud" stroke="#ff4d4d" strokeWidth={2} dot={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>

        </aside>
      </main>

      <footer className="text-center text-xs text-gray-600 mt-8">Built with ❤️ — Frontend connects to backend at <code>{API}</code></footer>
    </div>
  );
}
